[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>ScreenVault — UI & UX design inspiration for mobile & web apps</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
    <style>
        *, *::before, *::after {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        :root {
            --primary-dark: #141414;
            --white: #FFFFFF;
            --light-gray: #F5F5F5;
            --mid-gray: #E5E5E5;
            --text-gray: #6B6B6B;
            --accent: #5B5BFF;
            --accent-hover: #4A4AE6;
            --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
            --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
            --shadow-lg: 0 8px 24px rgba(0,0,0,0.12);
            --radius-sm: 8px;
            --radius-md: 12px;
            --radius-lg: 16px;
            --radius-full: 9999px;
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            color: var(--primary-dark);
            background: var(--white);
            line-height: 1.6;
            -webkit-font-smoothing: antialiased;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 24px;
        }

        /* Announcement Bar */
        .announcement-bar {
            background: var(--primary-dark);
            color: var(--white);
            text-align: center;
            padding: 10px 24px;
            font-size: 13px;
            font-weight: 500;
            letter-spacing: 0.02em;
        }

        .announcement-bar span {
            color: #A5A5FF;
        }

        /* Navigation */
        .nav {
            position: sticky;
            top: 0;
            background: rgba(255,255,255,0.95);
            backdrop-filter: blur(12px);
            border-bottom: 1px solid var(--mid-gray);
            z-index: 100;
            padding: 0 24px;
        }

        .nav-inner {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            align-items: center;
            justify-content: space-between;
            height: 64px;
        }

        .nav-logo {
            font-weight: 700;
            font-size: 18px;
            color: var(--primary-dark);
            text-decoration: none;
        }

        .nav-links {
            display: flex;
            gap: 32px;
            list-style: none;
        }

        .nav-links a {
            color: var(--text-gray);
            text-decoration: none;
            font-size: 14px;
            font-weight: 500;
            transition: color 0.2s;
        }

        .nav-links a:hover {
            color: var(--primary-dark);
        }

        .nav-cta {
            display: flex;
            gap: 12px;
        }

        .btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            padding: 10px 20px;
            border-radius: var(--radius-full);
            font-size: 14px;
            font-weight: 600;
            text-decoration: none;
            cursor: pointer;
            transition: all 0.2s;
            border: none;
        }

        .btn-primary {
            background: var(--accent);
            color: var(--white);
        }

        .btn-primary:hover {
            background: var(--accent-hover);
            transform: translateY(-1px);
        }

        .btn-secondary {
            background: transparent;
            color: var(--primary-dark);
            border: 1px solid var(--mid-gray);
        }

        .btn-secondary:hover {
            border-color: var(--primary-dark);
        }

        /* Hero Section */
        .hero {
            padding: 80px 24px 100px;
            text-align: center;
            background: linear-gradient(180deg, var(--white) 0%, var(--light-gray) 100%);
        }

        .hero-badge {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            background: var(--white);
            border: 1px solid var(--mid-gray);
            border-radius: var(--radius-full);
            padding: 6px 14px 6px 6px;
            font-size: 13px;
            color: var(--text-gray);
            margin-bottom: 24px;
            box-shadow: var(--shadow-sm);
        }

        .hero-badge-icon {
            width: 24px;
            height: 24px;
            background: var(--accent);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .hero-badge-icon svg {
            width: 14px;
            height: 14px;
            fill: white;
        }

        .hero h1 {
            font-size: clamp(36px, 6vw, 56px);
            font-weight: 700;
            line-height: 1.1;
            letter-spacing: -0.03em;
            margin-bottom: 20px;
        }

        .hero-subtitle {
            font-size: 18px;
            color: var(--text-gray);
            max-width: 540px;
            margin: 0 auto 32px;
        }

        .hero-cta {
            display: flex;
            gap: 12px;
            justify-content: center;
            flex-wrap: wrap;
        }

        /* Trusted By */
        .trusted-by {
            padding: 48px 24px;
            background: var(--white);
            border-top: 1px solid var(--light-gray);
            border-bottom: 1px solid var(--light-gray);
        }

        .trusted-by-label {
            text-align: center;
            font-size: 13px;
            color: var(--text-gray);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            margin-bottom: 24px;
        }

        .logo-marquee {
            display: flex;
            gap: 64px;
            animation: marquee 30s linear infinite;
        }

        .logo-marquee-wrapper {
            overflow: hidden;
        }

        .logo-item {
            font-size: 16px;
            font-weight: 600;
            color: var(--text-gray);
            white-space: nowrap;
            opacity: 0.6;
        }

        @keyframes marquee {
            0% { transform: translateX(0); }
            100% { transform: translateX(-50%); }
        }

        /* Stats Section */
        .stats {
            padding: 80px 24px;
            background: var(--light-gray);
        }

        .stats-header {
            text-align: center;
            margin-bottom: 48px;
        }

        .stats-header h2 {
            font-size: 14px;
            color: var(--text-gray);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            margin-bottom: 8px;
        }

        .stats-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 32px;
            max-width: 800px;
            margin: 0 auto;
        }

        .stat-card {
            text-align: center;
            padding: 32px;
            background: var(--white);
            border-radius: var(--radius-lg);
            box-shadow: var(--shadow-sm);
        }

        .stat-number {
            font-size: 48px;
            font-weight: 700;
            color: var(--primary-dark);
            line-height: 1;
            margin-bottom: 8px;
        }

        .stat-label {
            font-size: 14px;
            color: var(--text-gray);
        }

        /* Search Features Section */
        .features-search {
            padding: 80px 24px;
            background: var(--white);
        }

        .features-search h2 {
            text-align: center;
            font-size: clamp(28px, 4vw, 36px);
            font-weight: 700;
            margin-bottom: 12px;
        }

        .features-search-subtitle {
            text-align: center;
            color: var(--text-gray);
            margin-bottom: 48px;
        }

        .search-tabs {
            display: flex;
            justify-content: center;
            gap: 8px;
            margin-bottom: 32px;
            flex-wrap: wrap;
        }

        .search-tab {
            padding: 10px 20px;
            border-radius: var(--radius-full);
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s;
            background: var(--light-gray);
            color: var(--text-gray);
            border: none;
        }

        .search-tab:hover {
            background: var(--mid-gray);
        }

        .search-tab.active {
            background: var(--primary-dark);
            color: var(--white);
        }

        .filter-pills {
            display: flex;
            gap: 8px;
            justify-content: center;
            flex-wrap: wrap;
            margin-bottom: 40px;
            overflow-x: auto;
            padding-bottom: 8px;
        }

        .filter-pill {
            padding: 8px 16px;
            border-radius: var(--radius-full);
            font-size: 13px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s;
            background: var(--white);
            color: var(--text-gray);
            border: 1px solid var(--mid-gray);
            white-space: nowrap;
        }

        .filter-pill:hover {
            border-color: var(--primary-dark);
            color: var(--primary-dark);
        }

        .filter-pill.active {
            background: var(--primary-dark);
            color: var(--white);
            border-color: var(--primary-dark);
        }

        .screenshot-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 16px;
            max-width: 900px;
            margin: 0 auto;
        }

        .screenshot-card {
            aspect-ratio: 9/16;
            background: var(--light-gray);
            border-radius: var(--radius-md);
            overflow: hidden;
            box-shadow: var(--shadow-sm);
            transition: transform 0.2s, box-shadow 0.2s;
            position: relative;
        }

        .screenshot-card:hover {
            transform: translateY(-4px);
            box-shadow: var(--shadow-md);
        }

        .screenshot-card img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .screenshot-placeholder {
            width: 100%;
            height: 100%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            color: var(--text-gray);
            background: linear-gradient(135deg, var(--light-gray) 0%, var(--mid-gray) 100%);
        }

        /* Flows Section */
        .features-flows {
            padding: 80px 24px;
            background: var(--light-gray);
        }

        .features-flows h2 {
            text-align: center;
            font-size: clamp(28px, 4vw, 36px);
            font-weight: 700;
            margin-bottom: 12px;
        }

        .features-flows-subtitle {
            text-align: center;
            color: var(--text-gray);
            margin-bottom: 32px;
        }

        .flows-toggle {
            display: flex;
            justify-content: center;
            gap: 8px;
            margin-bottom: 40px;
        }

        .flows-toggle-btn {
            padding: 10px 24px;
            border-radius: var(--radius-full);
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s;
            background: var(--white);
            color: var(--text-gray);
            border: 1px solid var(--mid-gray);
        }

        .flows-toggle-btn:hover {
            border-color: var(--primary-dark);
        }

        .flows-toggle-btn.active {
            background: var(--primary-dark);
            color: var(--white);
            border-color: var(--primary-dark);
        }

        .flows-content {
            max-width: 900px;
            margin: 0 auto;
        }

        .flows-view {
            display: none;
        }

        .flows-view.active {
            display: block;
        }

        .flows-video-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 16px;
        }

        .flow-video-card {
            aspect-ratio: 9/16;
            background: var(--white);
            border-radius: var(--radius-md);
            overflow: hidden;
            box-shadow: var(--shadow-sm);
        }

        .flow-video-preview {
            height: 70%;
            background: linear-gradient(135deg, var(--mid-gray) 0%, var(--light-gray) 100%);
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .flow-video-preview svg {
            width: 40px;
            height: 40px;
            fill: var(--text-gray);
        }

        .flow-video-info {
            padding: 12px;
        }

        .flow-video-title {
            font-size: 14px;
            font-weight: 600;
            margin-bottom: 4px;
        }

        .flow-video-meta {
            font-size: 12px;
            color: var(--text-gray);
        }

        .flows-prototype-view {
            display: flex;
            flex-direction: column;
            gap: 16px;
        }

        .prototype-step {
            display: flex;
            gap: 16px;
            align-items: center;
            background: var(--white);
            border-radius: var(--radius-md);
            padding: 16px;
            box-shadow: var(--shadow-sm);
        }

        .prototype-step-number {
            width: 32px;
            height: 32px;
            background: var(--accent);
            color: var(--white);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            font-weight: 600;
            flex-shrink: 0;
        }

        .prototype-step-content {
            flex: 1;
        }

        .prototype-step-title {
            font-size: 14px;
            font-weight: 600;
            margin-bottom: 4px;
        }

        .prototype-step-desc {
            font-size: 13px;
            color: var(--text-gray);
        }

        .prototype-step-thumb {
            width: 60px;
            height: 100px;
            background: var(--light-gray);
            border-radius: var(--radius-sm);
            flex-shrink: 0;
        }

        /* Tools Section */
        .features-tools {
            padding: 80px 24px;
            background: var(--white);
        }

        .features-tools h2 {
            text-align: center;
            font-size: clamp(28px, 4vw, 36px);
            font-weight: 700;
            margin-bottom: 12px;
        }

        .features-tools-subtitle {
            text-align: center;
            color: var(--text-gray);
            margin-bottom: 48px;
        }

        .tools-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 24px;
            max-width: 1000px;
            margin: 0 auto;
        }

        .tool-card {
            background: var(--light-gray);
            border-radius: var(--radius-lg);
            padding: 32px 24px;
            text-align: center;
        }

        .tool-icon {
            width: 56px;
            height: 56px;
            background: var(--white);
            border-radius: var(--radius-md);
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 0 auto 16px;
            box-shadow: var(--shadow-sm);
        }

        .tool-icon svg {
            width: 28px;
            height: 28px;
            fill: var(--accent);
        }

        .tool-card h3 {
            font-size: 18px;
            font-weight: 600;
            margin-bottom: 8px;
        }

        .tool-card p {
            font-size: 14px;
            color: var(--text-gray);
        }

        /* Testimonials Section */
        .testimonials {
            padding: 80px 0;
            background: var(--light-gray);
            overflow: hidden;
        }

        .testimonials h2 {
            text-align: center;
            font-size: clamp(28px, 4vw, 36px);
            font-weight: 700;
            margin-bottom: 48px;
        }

        .testimonials-marquee-container {
            position: relative;
        }

        .testimonials-marquee {
            display: flex;
            gap: 16px;
            animation: marquee-up 40s linear infinite;
        }

        .testimonials-marquee-reverse {
            animation-direction: reverse;
        }

        @keyframes marquee-up {
            0% { transform: translateY(0); }
            100% { transform: translateY(-50%); }
        }

        .testimonial-card {
            background: var(--white);
            border-radius: var(--radius-lg);
            padding: 24px;
            width: 320px;
            flex-shrink: 0;
            box-shadow: var(--shadow-sm);
        }

        .testimonial-card-stars {
            display: flex;
            gap: 2px;
            margin-bottom: 12px;
        }

        .testimonial-card-stars svg {
            width: 16px;
            height: 16px;
            fill: #FFB800;
        }

        .testimonial-card p {
            font-size: 14px;
            line-height: 1.6;
            color: var(--primary-dark);
            margin-bottom: 16px;
        }

        .testimonial-card-author {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .testimonial-card-avatar {
            width: 40px;
            height: 40px;
            background: var(--accent);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--white);
            font-weight: 600;
            font-size: 14px;
        }

        .testimonial-card-info h4 {
            font-size: 14px;
            font-weight: 600;
        }

        .testimonial-card-info span {
            font-size: 12px;
            color: var(--text-gray);
        }

        /* CTA Section */
        .cta-section {
            padding: 100px 24px;
            background: var(--primary-dark);
            text-align: center;
        }

        .cta-section h2 {
            font-size: clamp(32px, 5vw, 44px);
            font-weight: 700;
            color: var(--white);
            margin-bottom: 16px;
        }

        .cta-section p {
            font-size: 18px;
            color: #A0A0A0;
            margin-bottom: 32px;
        }

        .cta-section .btn-primary {
            background: var(--white);
            color: var(--primary-dark);
        }

        .cta-section .btn-primary:hover {
            background: var(--light-gray);
        }

        .cta-section .btn-secondary {
            border-color: #444;
            color: var(--white);
        }

        .cta-section .btn-secondary:hover {
            border-color: var(--white);
        }

        .brand-marquee-wrapper {
            margin-top: 64px;
            overflow: hidden;
        }

        .brand-marquee {
            display: flex;
            gap: 48px;
            animation: marquee 25s linear infinite;
        }

        .brand-item {
            font-size: 14px;
            font-weight: 600;
            color: #666;
            white-space: nowrap;
        }

        /* Footer */
        .footer {
            padding: 64px 24px 32px;
            background: var(--white);
            border-top: 1px solid var(--light-gray);
        }

        .footer-grid {
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 48px;
            margin-bottom: 48px;
        }

        .footer-brand h3 {
            font-size: 18px;
            font-weight: 700;
            margin-bottom: 12px;
        }

        .footer-brand p {
            font-size: 14px;
            color: var(--text-gray);
            max-width: 280px;
        }

        .footer-col h4 {
            font-size: 13px;
            text-transform: uppercase;
            letter-spacing: 0.1em;
            color: var(--text-gray);
            margin-bottom: 16px;
        }

        .footer-col ul {
            list-style: none;
        }

        .footer-col li {
            margin-bottom: 8px;
        }

        .footer-col a {
            font-size: 14px;
            color: var(--primary-dark);
            text-decoration: none;
        }

        .footer-col a:hover {
            color: var(--accent);
        }

        .footer-bottom {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding-top: 32px;
            border-top: 1px solid var(--light-gray);
        }

        .footer-bottom p {
            font-size: 13px;
            color: var(--text-gray);
        }

        .footer-social {
            display: flex;
            gap: 16px;
        }

        .footer-social a {
            color: var(--text-gray);
            transition: color 0.2s;
        }

        .footer-social a:hover {
            color: var(--primary-dark);
        }

        .footer-social svg {
            width: 20px;
            height: 20px;
        }

        /* Responsive */
        @media (max-width: 768px) {
            .nav-links {
                display: none;
            }

            .stats-grid {
                grid-template-columns: 1fr;
                gap: 16px;
            }

            .screenshot-grid {
                grid-template-columns: repeat(2, 1fr);
            }

            .flows-video-grid {
                grid-template-columns: 1fr;
            }

            .tools-grid {
                grid-template-columns: 1fr;
            }

            .footer-grid {
                grid-template-columns: 1fr 1fr;
            }

            .footer-brand {
                grid-column: span 2;
            }

            .footer-bottom {
                flex-direction: column;
                gap: 16px;
                text-align: center;
            }

            .testimonial-card {
                width: 280px;
            }
        }

        @media (max-width: 480px) {
            .hero {
                padding: 60px 24px 80px;
            }

            .hero h1 {
                font-size: 28px;
            }

            .hero-subtitle {
                font-size: 16px;
            }

            .stat-number {
                font-size: 36px;
            }

            .screenshot-grid {
                grid-template-columns: 1fr 1fr;
                gap: 12px;
            }

            .filter-pills {
                justify-content: flex-start;
            }

            .footer-grid {
                grid-template-columns: 1fr;
            }

            .footer-brand {
                grid-column: span 1;
            }
        }
    </style>
</head>
<body>
    <!-- Announcement Bar -->
    <div class="announcement-bar">
        2025 ScreenVault Awards — Celebrating the best on the internet <span>&rarr;</span>
    </div>

    <!-- Navigation -->
    <nav class="nav">
        <div class="nav-inner">
            <a href="#" class="nav-logo">ScreenVault</a>
            <ul class="nav-links">
                <li><a href="#">Pricing</a></li>
                <li><a href="#">Awards</a></li>
                <li><a href="#">Log in</a></li>
            </ul>
            <div class="nav-cta">
                <a href="#" class="btn btn-secondary">Log in</a>
                <a href="#" class="btn btn-primary">Join for free</a>
            </div>
        </div>
    </nav>

    <!-- Hero Section -->
    <section class="hero">
        <div class="container">
            <div class="hero-badge">
                <div class="hero-badge-icon">
                    <svg viewBox="0 0 24 24"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z"/></svg>
                </div>
                1,150+ apps available
            </div>
            <h1>Discover real-world design inspiration.</h1>
            <p class="hero-subtitle">Featuring over 1,000 iOS & Web apps, and 200 sites — New content weekly.</p>
            <div class="hero-cta">
                <a href="#" class="btn btn-primary">Join for free</a>
                <a href="#" class="btn btn-secondary">See our plans</a>
            </div>
        </div>
    </section>

    <!-- Trusted By -->
    <section class="trusted-by">
        <div class="container">
            <p class="trusted-by-label">Trusted by design teams at</p>
            <div class="logo-marquee-wrapper">
                <div class="logo-marquee">
                    <span class="logo-item">Figma</span>
                    <span class="logo-item">Airbnb</span>
                    <span class="logo-item">Spotify</span>
                    <span class="logo-item">Stripe</span>
                    <span class="logo-item">Uber</span>
                    <span class="logo-item">Notion</span>
