    <script>
        // Stats Counter Animation
        const statsSection = document.getElementById('stats');
        const statNumbers = document.querySelectorAll('.stat-number');
        let statsAnimated = false;

        function animateCounter(el, target, duration) {
            const start = 0;
            const increment = target / (duration / 16);
            let current = start;

            function updateCounter() {
                current += increment;
                if (current < target) {
                    el.textContent = Math.floor(current).toLocaleString();
                    requestAnimationFrame(updateCounter);
                } else {
                    el.textContent = target.toLocaleString();
                }
            }

            updateCounter();
        }

        function checkStatsInView() {
            if (statsAnimated) return;
            const rect = statsSection.getBoundingClientRect();
            const isInView = rect.top < window.innerHeight && rect.bottom > 0;

            if (isInView) {
                statsAnimated = true;
                statNumbers.forEach((el, index) => {
                    const target = parseInt(el.dataset.target);
                    setTimeout(() => {
                        animateCounter(el, target, 2000);
                    }, index * 200);
                });
            }
        }

        window.addEventListener('scroll', checkStatsInView);
        checkStatsInView();

        // Search Tabs
        const searchTabs = document.querySelectorAll('.search-tab');
        searchTabs.forEach(tab => {
            tab.addEventListener('click', () => {
                searchTabs.forEach(t => t.classList.remove('active'));
                tab.classList.add('active');
            });
        });

        // Filter Pills
        const filterPills = document.querySelectorAll('.filter-pill');
        filterPills.forEach(pill => {
            pill.addEventListener('click', () => {
                filterPills.forEach(p => p.classList.remove('active'));
                pill.classList.add('active');
            });
        });

        // Flows Toggle
        const flowsToggleBtns = document.querySelectorAll('.flows-toggle-btn');
        const flowsViews = document.querySelectorAll('.flows-view');

        flowsToggleBtns.forEach(btn => {
            btn.addEventListener('click', () => {
                const toggleType = btn.dataset.toggle;

                flowsToggleBtns.forEach(b => b.classList.remove('active'));
                btn.classList.add('active');

                flowsViews.forEach(view => {
                    view.classList.remove('active');
                    if (view.dataset.view === toggleType) {
                        view.classList.add('active');
                    }
                });
            });
        });
    </script>
